#include "network/java/JavaFireworkGeometry.h"
#include <cassert>
#include <iostream>
int main(){JavaFireworkRandom f(0),g(0);assert(f.nextFloat()==.73096776f);assert(std::abs(g.nextGaussian()-.8025330637390305)<1e-14);for(auto pair:std::vector<std::pair<std::string,size_t>>{{"small_ball",98},{"large_ball",386},{"star",121},{"creeper",265},{"burst",70}}){JavaFireworkRandom random(12345);auto vectors=JavaFireworkGeometry::velocities(pair.first,random);assert(vectors.size()==pair.second);for(const auto& v:vectors)for(double c:v)assert(std::isfinite(c));if(pair.first=="star")assert(vectors.front()==JavaFireworkGeometry::Vector({{0,.5,0}}));if(pair.first=="creeper")assert(vectors.front()==JavaFireworkGeometry::Vector({{0,.1,0}}));}
JavaFireworkRandom a(5),b(5);auto still=JavaFireworkGeometry::velocities("burst",a),moving=JavaFireworkGeometry::velocities("burst",b,{{2,4,6}});for(size_t i=0;i<70;++i){assert(std::abs(moving[i][0]-still[i][0]-1)<1e-12);assert(std::abs(moving[i][1]-still[i][1]-2)<1e-12);assert(std::abs(moving[i][2]-still[i][2]-3)<1e-12);}
assert(JavaFireworkGeometry::sprite(0,48)==0&&JavaFireworkGeometry::sprite(7,48)==1&&JavaFireworkGeometry::sprite(48,48)==7);assert(JavaFireworkGeometry::visible(15,48,true));assert(!JavaFireworkGeometry::visible(16,48,true)&&!JavaFireworkGeometry::visible(17,48,true));assert(JavaFireworkGeometry::visible(18,48,true)&&JavaFireworkGeometry::visible(20,48,true)&&!JavaFireworkGeometry::visible(21,48,true));assert(std::abs(JavaFireworkGeometry::alpha(25,48)-.9791666667f)<1e-7);assert(JavaFireworkGeometry::flashSize(1,0)==0);assert(std::abs(JavaFireworkGeometry::flashSize(3,0)-7.1f)<1e-6);assert(std::abs(JavaFireworkGeometry::flashAlpha(3,0)-.35f)<1e-6);std::cout<<"Official firework geometry/RNG golden values:5shapes exactcounts and anchors, inherited burst motion, sprite/twinkle/alpha/flash timelines PASS\n";}
